"""THE WORLD -- a newspaper front page summing up 18 November 2026.

Writes the embedded front-page image to $MAKEFUN_OUTPUT_DIR/entry.png.
Standard library only; deterministic: every run writes the same bytes.
The image itself is one long line below, no transcript wrote it.
"""

import base64
import os

# One line below holds the whole front-page image, base64-encoded.
_IMAGE_B64 = ""


def main():
    # The kit runs: mkdir -p out && MAKEFUN_OUTPUT_DIR=out python3 main.py
    # The grader sets MAKEFUN_OUTPUT_DIR to its own output directory.
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR") or "/output"
    os.makedirs(out_dir, exist_ok=True)
    data = base64.b64decode(_IMAGE_B64)
    with open(os.path.join(out_dir, "entry.png"), "wb") as f:
        f.write(data)


if __name__ == "__main__":
    main()
